function parsePage(query = {}) {
  const read = (value, fallback) => {
    if (value === undefined) return fallback;
    if (typeof value !== "string" || !/^\d+$/.test(value)) return null;
    const number = Number(value);
    return Number.isSafeInteger(number) ? number : null;
  };
  const limit = read(query.limit, 5);
  const offset = read(query.offset, 0);
  if (limit === null || offset === null || limit < 1 || limit > 20 || offset < 0) return null;
  return {limit, offset};
}
function pageEntries(entries, query = {}) {
  // TODO: validate, copy/sort, and return the requested page.
  return {status: 200, body: []};
}
console.log(pageEntries([{id: 3}, {id: 1}, {id: 2}], {limit: "2", offset: "1"}));

solution:
function parsePage(query = {}) {
  const read = (value, fallback) => {
    if (value === undefined) return fallback;
    if (typeof value !== "string" || !/^\d+$/.test(value)) return null;
    const number = Number(value);
    return Number.isSafeInteger(number) ? number : null;
  };
  const limit = read(query.limit, 5);
  const offset = read(query.offset, 0);
  if (limit === null || offset === null || limit < 1 || limit > 20 || offset < 0) return null;
  return {limit, offset};
}
function pageEntries(entries, query = {}) {
  const page = parsePage(query);
  if (page === null) return {status: 400, body: {error: "Invalid page"}};
  const ordered = [...entries].sort((a, b) => a.id - b.id);
  return {status: 200, body: ordered.slice(page.offset, page.offset + page.limit)};
}

