function readTitle(text) {
  // Parse the text, check the shape, and return a string title or null.
}
console.log(readTitle('{"title":"Ocean life"}'));

solution:
function readTitle(text) {
  try {
    const value = JSON.parse(text);
    if (value === null || typeof value !== "object" || Array.isArray(value)) return null;
    return typeof value.title === "string" ? value.title : null;
  } catch (error) {
    return null;
  }
}
console.log(readTitle('{"title":"Ocean life"}'));

