solution:
function taskReducer(tasks, action) {
  if (action.type === "add") {
    if (tasks.some(task => task.id === action.id)) return tasks;
    return [...tasks, {id: action.id, title: action.title, done: false}];
  }
  if (action.type === "toggle") {
    return tasks.map(task => task.id === action.id
      ? {...task, done: !task.done} : task);
  }
  return tasks;
}
function App() {
  const [tasks, dispatch] = React.useReducer(taskReducer, []);
  return <main>
    <button onClick={() => dispatch({type:"add", id:"read", title:"Read"})}>Add reading task</button>
    <ul>{tasks.map(task => <li key={task.id}>
      <span>{task.title}: {task.done ? "Done" : "To do"}</span>
      <button aria-label={"Toggle " + task.title} onClick={() => dispatch({type:"toggle", id:task.id})}>Toggle</button>
    </li>)}</ul>
    <p role="status">{tasks.length} {tasks.length === 1 ? "task" : "tasks"}</p>
  </main>;
}

